  private val HUFF_CODES: Array[Int] =
    HUFF_CODES_TEXT.split(",").map(s => Integer.parseInt(s.trim.stripPrefix("0x"), 16))
  private val HUFF_LENS: Array[Int] =
    HUFF_LENS_TEXT.split(",").map(s => Integer.parseInt(s.trim))

  private val HUFF_DECODE = new java.util.HashMap[Long, Integer]()
  for (sym <- HUFF_CODES.indices) {
    HUFF_DECODE.put((HUFF_LENS(sym).toLong << 32) | (HUFF_CODES(sym).toLong & 0xffffffffL), Integer.valueOf(sym))
  }

  private val CLOSED_MARK = new Array[Byte](0)

  def huffDecode(data: Array[Byte], off: Int, len: Int): String = {
    val out = new StringBuilder()
    var code = 0L
    var bits = 0
    for (i <- 0 until len) {
      val b = data(off + i) & 0xff
      for (j <- 7 to 0 by -1) {
        code = (code << 1) | ((b >> j) & 1)
        bits += 1
        val sym = HUFF_DECODE.get((bits.toLong << 32) | code)
        if (sym != null) {
          if (sym.intValue() == 256) throw new IOException("huffman EOS symbol")
          out.append(sym.intValue().toChar)
          code = 0
          bits = 0
        } else if (bits > 30) {
          throw new IOException("huffman code too long")
        }
      }
    }
    out.toString
  }

  def writeInt(out: ByteArrayOutputStream, value: Int, prefixBits: Int, prefix: Int): Unit = {
    val mask = (1 << prefixBits) - 1
    if (value < mask) {
      out.write(prefix | value)
      return
    }
    out.write(prefix | mask)
    var v = value - mask
    while (v >= 0x80) {
      out.write((v & 0x7f) | 0x80)
      v = v >> 7
    }
    out.write(v)
  }

  def writeString(out: ByteArrayOutputStream, value: String): Unit = {
    val raw = value.getBytes(StandardCharsets.UTF_8)
    writeInt(out, raw.length, 7, 0)
    out.write(raw, 0, raw.length)
  }

  def writeLiteralIndexedName(out: ByteArrayOutputStream, index: Int, value: String): Unit = {
    writeInt(out, index, 4, 0)
    writeString(out, value)
  }

  def writeLiteralNewName(out: ByteArrayOutputStream, name: String, value: String): Unit = {
    writeInt(out, 0, 4, 0)
    writeString(out, name)
    writeString(out, value)
  }

  def gunzip(data: Array[Byte]): Array[Byte] = {
    val out = new ByteArrayOutputStream()
    val gz = new GZIPInputStream(new ByteArrayInputStream(data))
    try {
      gz.transferTo(out)
    } finally {
      gz.close()
    }
    out.toByteArray
  }

  def gzip(data: Array[Byte]): Array[Byte] = {
    val out = new ByteArrayOutputStream()
    val gz = new GZIPOutputStream(out)
    try {
      gz.write(data)
    } finally {
      gz.close()
    }
    out.toByteArray
  }

  def percentDecode(value: String): String = {
    val bytes = new ByteArrayOutputStream()
    var i = 0
    while (i < value.length) {
      val c = value.charAt(i)
      var consumed = false
      if (c == '%' && i + 2 < value.length) {
        val hi = Character.digit(value.charAt(i + 1), 16)
        val lo = Character.digit(value.charAt(i + 2), 16)
        if (hi >= 0 && lo >= 0) {
          bytes.write((hi << 4) | lo)
          i += 2
          consumed = true
        }
      }
      if (!consumed) bytes.write(c.toByte)
      i += 1
    }
    bytes.toString(StandardCharsets.UTF_8)
  }

  /** Cleartext (h2c, prior knowledge) connection to authority. */
  def dial(authority: String): Http2Transport = new Http2Transport(authority, null, null)

  /**
   * TLS connection to authority (ALPN h2). context supplies
   * trust/key material; serverName overrides SNI/verification
   * name (defaults to the authority host).
   */
  def dialTls(authority: String, context: SSLContext, serverName: String): Http2Transport =
    new Http2Transport(
      authority,
      (if (context != null) context.getSocketFactory else SSLSocketFactory.getDefault()).asInstanceOf[SSLSocketFactory],
      serverName)

  class HpackDecoder {
    val dynamic = new java.util.ArrayList[Array[String]]()
    var dynamicSize = 0

    def entry(index: Int): Array[String] = {
      if (index <= 0) throw new IOException("bad hpack index 0")
      if (index <= STATIC_TABLE.length) {
        val e = STATIC_TABLE(index - 1)
        return Array(e(0), e(1))
      }
      val j = index - STATIC_TABLE.length - 1
      if (j >= dynamic.size()) throw new IOException(s"bad hpack dynamic index $index")
      dynamic.get(j)
    }

    def add(name: String, value: String): Unit = {
      dynamic.add(0, Array(name, value))
      dynamicSize += name.length + value.length + 32
      while (dynamicSize > HpackDecoder.MAX_DYNAMIC && !dynamic.isEmpty) {
        val e = dynamic.remove(dynamic.size() - 1)
        dynamicSize -= e(0).length + e(1).length + 32
      }
    }

    def readInt(data: Array[Byte], pos: Array[Int], prefixBits: Int): Int = {
      val mask = (1 << prefixBits) - 1
      var value = data(pos(0)) & mask
      pos(0) += 1
      if (value < mask) return value
      var shift = 0
      var done = false
      while (!done) {
        if (pos(0) >= data.length) throw new IOException("truncated hpack int")
        val b = data(pos(0)) & 0xff
        pos(0) += 1
        value += (b & 0x7f) << shift
        shift += 7
        if ((b & 0x80) == 0) done = true
      }
      value
    }

    def readString(data: Array[Byte], pos: Array[Int]): String = {
      if (pos(0) >= data.length) throw new IOException("truncated hpack string")
      val huffman = (data(pos(0)) & 0x80) != 0
      val len = readInt(data, pos, 7)
      if (pos(0) + len > data.length) throw new IOException("truncated hpack string body")
      val value = if (huffman) {
        huffDecode(data, pos(0), len)
      } else {
        new String(data, pos(0), len, StandardCharsets.UTF_8)
      }
      pos(0) += len
      value
    }

    def decode(block: Array[Byte]): List[Array[String]] = {
      val out = scala.collection.mutable.ListBuffer[Array[String]]()
      val pos = Array(0)
      while (pos(0) < block.length) {
        val b = block(pos(0)) & 0xff
        if ((b & 0x80) != 0) {
          val index = readInt(block, pos, 7)
          out += entry(index)
        } else if ((b & 0xe0) == 0x20) {
          readInt(block, pos, 5)
        } else {
          val incremental = (b & 0xc0) == 0x40
          val index = readInt(block, pos, if (incremental) 6 else 4)
          val name = if (index > 0) entry(index)(0) else readString(block, pos)
          val value = readString(block, pos)
          out += Array(name, value)
          if (incremental) add(name, value)
        }
      }
      out.toList
    }
  }

  object HpackDecoder {
    val MAX_DYNAMIC = 4096
  }
}
